{# الرسم الرسمي لمعاملة — Murasalat Correspondence official record.

   Arabic-first on purpose: the labels are written in Arabic here rather than wrapped in
   _(), so a printed document never depends on a translation file being complete. The
   English Select/Link values stored on the record are mapped to Arabic in the dicts
   below, with the stored value as the fallback.
#}
{% set DIRECTION_AR = {"Incoming": "وارد", "Outgoing": "صادر", "Internal": "داخلي"} %}
{% set ACTIVITY_AR = {
    "Created": "إنشاء",
    "Status Changed": "تغيير الحالة",
    "Registered": "تسجيل",
    "Closed": "إغلاق",
    "Sealed": "ختم",
    "Reopened": "إعادة فتح",
    "Referral Sent": "إرسال إحالة",
    "Referral Received": "استلام إحالة",
    "Referral Completed": "إكمال إحالة",
} %}
{% if doc.correspondence_direction == "Incoming" %}
    {% set FROM_LABEL = "المُرسِل" %}{% set FROM_VALUE = doc.incoming_source_entity %}
    {% set TO_LABEL = "القسم المستلِم" %}{% set TO_VALUE = doc.incoming_target_entry %}
{% elif doc.correspondence_direction == "Outgoing" %}
    {% set FROM_LABEL = "القسم المُرسِل" %}{% set FROM_VALUE = doc.outgoing_source_entity %}
    {% set TO_LABEL = "الجهة المستلِمة" %}{% set TO_VALUE = doc.outgoing_target_entry %}
{% else %}
    {% set FROM_LABEL = "من قسم" %}{% set FROM_VALUE = doc.internal_source_entity %}
    {% set TO_LABEL = "إلى قسم" %}{% set TO_VALUE = doc.internal_target_entry %}
{% endif %}
<style>
  @page { size: A4; margin: 12mm; }

  .mo-print {
    direction: rtl;
    text-align: right;
    font-family: "Noto Naskh Arabic", "Amiri", "Traditional Arabic", "Segoe UI", Tahoma, Arial, sans-serif;
    color: #17231f;
    font-size: 10.5pt;
    line-height: 1.75;
  }
  .mo-print .head { width: 100%; border-collapse: collapse; border-bottom: 2.2pt solid #123c35; padding-bottom: 2mm; }
  .mo-print .head td { border: none; vertical-align: bottom; padding: 0 0 2mm 0; }
  .mo-print .title { font-size: 15pt; font-weight: bold; color: #123c35; }
  .mo-print .subtitle { font-size: 9.5pt; color: #55655f; }
  .mo-print .doc-no { direction: ltr; text-align: left; font-size: 13pt; font-weight: bold; color: #123c35; letter-spacing: 0.4pt; }
  .mo-print .badges { margin: 3mm 0 4mm 0; }
  .mo-print .badge {
    display: inline-block; border: 0.9pt solid #123c35; border-radius: 2pt;
    padding: 0.6mm 2.6mm; margin-left: 2mm; font-size: 9pt; font-weight: bold;
  }
  .mo-print .badge.plain { border-color: #8fa39c; color: #3c4a45; font-weight: normal; }
  .mo-print .badge.alert { border-color: #b03a2e; color: #b03a2e; background: #fdf3f1; }

  .mo-print table.grid { width: 100%; border-collapse: collapse; margin: 0 0 4mm 0; }
  .mo-print table.grid th {
    background: #eef3f1; color: #123c35; text-align: right; font-size: 9.4pt;
    border: 0.6pt solid #c9d8d3; padding: 1.6mm 2mm; font-weight: bold;
  }
  .mo-print table.grid td { border: 0.6pt solid #c9d8d3; padding: 1.6mm 2mm; vertical-align: top; }
  .mo-print table.meta td.label { background: #f6f9f8; width: 22%; font-size: 9.2pt; color: #3c4a45; }
  .mo-print table.meta td.value { width: 28%; font-weight: bold; }
  .mo-print .mono { direction: ltr; text-align: left; font-family: "DejaVu Sans Mono", Consolas, monospace; font-size: 8.2pt; }

  .mo-print .section-title {
    font-size: 11pt; font-weight: bold; color: #123c35; margin: 4mm 0 1.5mm 0;
    border-right: 3pt solid #2f6b5f; padding-right: 2mm;
  }
  .mo-print .body-box {
    border: 0.6pt solid #c9d8d3; background: #fbfdfc; padding: 3mm 3.5mm; min-height: 26mm;
    white-space: pre-wrap;
  }
  .mo-print .parties td { text-align: center; width: 50%; }
  .mo-print .parties .role { font-size: 9pt; color: #55655f; }
  .mo-print .parties .who { font-size: 11pt; font-weight: bold; }

  .mo-print table.sign { width: 100%; border-collapse: separate; border-spacing: 2.5mm 0; margin-top: 2mm; }
  .mo-print table.sign td { border: 0.6pt solid #c9d8d3; padding: 2mm; vertical-align: top; width: 33.3%; }
  .mo-print .sign-role { font-size: 9pt; color: #3c4a45; font-weight: bold; }
  .mo-print .sign-space { height: 15mm; }
  .mo-print .sign-line { border-top: 0.6pt solid #8fa39c; font-size: 8.4pt; color: #55655f; padding-top: 1mm; }

  .mo-print .audit { margin-top: 4mm; border: 0.9pt solid #123c35; background: #f4f8f6; padding: 3mm 3.5mm; font-size: 9pt; }
  .mo-print .audit .hash { direction: ltr; text-align: left; word-break: break-all; font-family: "DejaVu Sans Mono", Consolas, monospace; font-size: 7.6pt; }
  .mo-print .trail { font-size: 8.6pt; }
  .mo-print .trail th { font-size: 8.6pt; }
  .mo-print .foot { margin-top: 5mm; border-top: 0.6pt solid #c9d8d3; padding-top: 1.5mm; font-size: 8.2pt; color: #55655f; }
  .mo-print .muted { color: #7b8b86; }
</style>

<div class="mo-print" dir="rtl">

  <table class="head">
    <tr>
      <td>
        <div class="title">معاملة</div>
        <div class="subtitle">{{ doc.correspondence_direction and DIRECTION_AR.get(doc.correspondence_direction, doc.correspondence_direction) or "" }}</div>
      </td>
      <td class="doc-no">{{ doc.name }}</td>
    </tr>
  </table>

  <div class="badges">
    {% if doc.confidentiality %}<span class="badge">{{ doc.confidentiality }}</span>{% endif %}
    {% if doc.importance %}<span class="badge plain">{{ doc.importance }}</span>{% endif %}
    {% if doc.transaction_type %}<span class="badge plain">{{ doc.transaction_type }}</span>{% endif %}
    {% if doc.workflow_state %}<span class="badge plain">{{ doc.workflow_state }}</span>{% endif %}
    {% if doc.record_sealed_on %}<span class="badge alert">مختومة</span>{% endif %}
  </div>

  <table class="grid parties">
    <tr>
      <td>
        <div class="role">{{ FROM_LABEL }}</div>
        <div class="who">{{ FROM_VALUE or "—" }}</div>
      </td>
      <td>
        <div class="role">{{ TO_LABEL }}</div>
        <div class="who">{{ TO_VALUE or "—" }}</div>
      </td>
    </tr>
  </table>

  <table class="grid meta">
    <tr>
      <td class="label">الموضوع</td>
      <td class="value" colspan="3">{{ doc.subject or "—" }}</td>
    </tr>
    <tr>
      <td class="label">رقم المعاملة</td>
      <td class="value">{{ doc.name }}</td>
      <td class="label">تاريخ التسجيل في النظام</td>
      <td class="value">{{ frappe.utils.getdate(doc.creation).strftime("%d-%m-%Y") if doc.creation else "—" }}</td>
    </tr>
    <tr>
      <td class="label">الرقم الخارجي</td>
      <td class="value">{{ doc.external_letter_number or "—" }}</td>
      <td class="label">تاريخ الخطاب الخارجي</td>
      <td class="value">{{ frappe.utils.getdate(doc.external_letter_date).strftime("%d-%m-%Y") if doc.external_letter_date else "—" }}</td>
    </tr>
    <tr>
      <td class="label">الموعد النهائي</td>
      <td class="value">{{ frappe.utils.getdate(doc.due_date).strftime("%d-%m-%Y") if doc.due_date else "—" }}</td>
      <td class="label">عدد الصفحات</td>
      <td class="value">{{ doc.page_count or "—" }}</td>
    </tr>
    <tr>
      <td class="label">القسم الحائز حاليًا</td>
      <td class="value">{{ doc.current_holder or "—" }}</td>
      <td class="label">المعني بالمعاملة</td>
      <td class="value">{{ doc.concerned_person or "—" }}</td>
    </tr>
  </table>

  <div class="section-title">المضمون</div>
  <div class="body-box">{{ doc.notes or "—" }}</div>

  {% if doc.attachments %}
  <div class="section-title">المرفقات ({{ doc.attachments | length }})</div>
  <table class="grid">
    <tr>
      <th style="width: 8mm">#</th>
      <th style="width: 32mm">النوع</th>
      <th>الملف</th>
      <th style="width: 20mm">سرّي</th>
    </tr>
    {% for att in doc.attachments %}
    <tr>
      <td>{{ loop.index }}</td>
      <td>{{ att.attachment_type or "—" }}</td>
      <td>
        {% if att.is_secret %}
          <span class="muted">مرفق سرّي — يُطلب من الأرشيف</span>
        {% elif att.file %}
          {{ att.file.split("/")[-1] }}
        {% else %}
          <span class="muted">—</span>
        {% endif %}
      </td>
      <td>{{ "نعم" if att.is_secret else "لا" }}</td>
    </tr>
    {% endfor %}
  </table>
  {% endif %}

  <table class="sign">
    <tr>
      <td>
        <div class="sign-role">الموظف المُحرِّر</div>
        <div class="sign-space"></div>
        <div class="sign-line">الاسم والتوقيع والتاريخ</div>
      </td>
      <td>
        <div class="sign-role">المستلِم</div>
        <div class="sign-space"></div>
        <div class="sign-line">الاسم والتوقيع والتاريخ</div>
      </td>
      <td>
        <div class="sign-role">الختم الرسمي</div>
        <div class="sign-space"></div>
        <div class="sign-line">حسب الأصول</div>
      </td>
    </tr>
  </table>

  {% if doc.record_sealed_on %}
  <div class="audit">
    <div class="sign-role">تدقيق السلامة — سجل مختوم</div>
    <table class="grid meta" style="margin: 2mm 0 0 0">
      <tr>
        <td class="label">تاريخ الختم</td>
        <td class="value">{{ frappe.utils.get_datetime(doc.record_sealed_on).strftime("%d-%m-%Y %H:%M") }}</td>
        <td class="label">خُتم بواسطة</td>
        <td class="value">{{ doc.record_sealed_by or "—" }}</td>
      </tr>
      {% if doc.seal_reason %}
      <tr>
        <td class="label">سبب الختم</td>
        <td class="value" colspan="3">{{ doc.seal_reason }}</td>
      </tr>
      {% endif %}
      {% if doc.reopened_on %}
      <tr>
        <td class="label">أُعيد فتحها في</td>
        <td class="value">{{ frappe.utils.get_datetime(doc.reopened_on).strftime("%d-%m-%Y %H:%M") }}</td>
        <td class="label">بواسطة</td>
        <td class="value">{{ doc.reopened_by or "—" }}</td>
      </tr>
      {% endif %}
    </table>
    {% if doc.integrity_hash %}
    <div style="margin-top: 2mm">بصمة السلامة (SHA-256):</div>
    <div class="hash">{{ doc.integrity_hash }}</div>
    {% endif %}
  </div>
  {% endif %}

  {% if doc.activities %}
  <div class="section-title">سجل الحركة</div>
  <table class="grid trail">
    <tr>
      <th style="width: 30mm">التاريخ</th>
      <th style="width: 28mm">الحدث</th>
      <th style="width: 40mm">المنفّذ</th>
      <th>التفصيل</th>
    </tr>
    {% for a in doc.activities %}
    <tr>
      <td class="mono">{{ frappe.utils.get_datetime(a.activity_on).strftime("%d-%m-%Y %H:%M") if a.activity_on else "—" }}</td>
      <td>{{ ACTIVITY_AR.get(a.activity_type, a.activity_type) }}</td>
      <td>{{ a.actor or "—" }}</td>
      <td>{{ a.details or "—" }}</td>
    </tr>
    {% endfor %}
  </table>
  {% endif %}

  <div class="foot">
    طُبع بواسطة {{ frappe.session.user }} — {{ frappe.utils.get_datetime(frappe.utils.now()).strftime("%d-%m-%Y %H:%M") }}
    {% if doc.correspondence_direction %} · اتجاه المعاملة: {{ DIRECTION_AR.get(doc.correspondence_direction, doc.correspondence_direction) }}{% endif %}
  </div>

</div>
